#include "wsoundammo89.h"
static wsound89_i16 sat(wsound89_i32 v){if(v>32767)return 32767;if(v<-32768)return -32768;return(wsound89_i16)v;}static wsound89_i16 nz(wsoundammo89_context*c){c->state=c->state*1664525U+1013904223U;return(wsound89_i16)((c->state>>16)&65535U);}
wsound89_result wsoundammo89_init(wsoundammo89_context*c,wsound89_u32 seed){if(!c)return WSOUND89_EINVAL;c->state=seed?seed:0x414D4D4FU;c->accum=0;c->env=c->impulse=c->res1=c->res2=c->low=0;c->fill_q15=32767;c->motion_q15=0;c->active=0;c->type=WSOUNDAMMO89_BOX_MAG;return WSOUND89_OK;}
wsound89_result wsoundammo89_trigger(wsoundammo89_context*c,wsoundammo89_type t,wsound89_u16 fill,wsound89_u16 motion){if(!c||(wsound89_u32)t>4U)return WSOUND89_EINVAL;c->type=t;c->fill_q15=fill;c->motion_q15=motion;c->env=30000;c->active=1;c->accum=0;return WSOUND89_OK;}
wsound89_i16 wsoundammo89_process_sample(wsoundammo89_context*c){wsound89_i32 n,mix;wsound89_u32 rate;if(!c||!c->active)return 0;rate=700U+((32767U-c->fill_q15)>>2)+(c->motion_q15>>3);c->accum+=rate;if(c->accum>32768U){c->accum-=32768U;n=nz(c);c->impulse=((wsound89_i32)n*(7000+(c->motion_q15>>1)))>>15;}else c->impulse=(c->impulse*17000)>>15;n=nz(c);c->low+=(n-c->low)>>5;c->res1+=(c->impulse-c->res1)>>2;c->res2+=(c->res1-c->res2)>>4;mix=c->impulse;if(c->type==WSOUNDAMMO89_DRUM)mix+=(c->res2>>1);else if(c->type==WSOUNDAMMO89_TUBE)mix+=(c->res1>>2);else if(c->type==WSOUNDAMMO89_BELT_BOX)mix+=(c->low>>3);else if(c->type==WSOUNDAMMO89_LOOSE_SHELLS)mix+=c->res1>>1;mix=(mix*c->env)>>15;c->env-=(c->env>>8)+8;if(c->env<20){c->env=0;c->active=0;}return sat(mix);}
